<div class="content-wrapper"><section class="content-header"><h1>Profil Perusahaan Operator</h1></section><section class="content"><?php $this->load->view('pipeline/billing_notice'); ?><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><form method="get"><label>Area</label><select name="area" class="form-control" onchange="this.form.submit()"><?php foreach($areas as $a): ?><option value="<?= (int)$a['SpbbID'] ?>" <?= (int)$a['SpbbID']===$area?'selected':'' ?>><?= html_escape($a['SpbbName']) ?></option><?php endforeach; ?></select></form></div></div><?php if($area): ?><div class="box box-success"><div class="box-body"><p>Nama dan identitas perusahaan pengelola area. Profil ini dipakai bersama operator pada area yang sama.</p><form method="post" enctype="multipart/form-data"><?php $this->load->view('pipeline/billing_token'); ?><input type="hidden" name="SpbbID" value="<?= $area ?>"><input type="hidden" name="Version" value="<?= (int)($form['Version']??0) ?>"><div class="row"><?php foreach(array('CompanyName'=>'Nama Perusahaan','NIB'=>'NIB','NPWP'=>'NPWP','Address'=>'Alamat Perusahaan','Phone'=>'Telepon','Email'=>'Email','PicName'=>'Nama Penanggung Jawab') as $k=>$label): ?><div class="col-md-6 form-group"><label><?= $label ?></label><?php if($k==='Address'): ?><textarea name="<?= $k ?>" maxlength="1000" class="form-control"><?= html_escape($form[$k]??'') ?></textarea><?php else: ?><input name="<?= $k ?>" class="form-control" type="<?= $k==='Email'?'email':'text' ?>" maxlength="<?= array('CompanyName'=>200,'NIB'=>30,'NPWP'=>30,'Phone'=>50,'Email'=>150,'PicName'=>150)[$k] ?>" value="<?= html_escape($form[$k]??'') ?>" <?= $k==='CompanyName'?'required':'' ?>><?php endif; ?></div><?php endforeach; ?></div><div class="row"><?php foreach(array('Logo'=>'Logo Perusahaan (JPG / PNG)','Identity'=>'Dokumen Identitas Perusahaan (PDF / JPG / PNG)') as $kind=>$label): ?><div class="col-md-6 form-group"><label><?= $label ?></label><input type="file" class="form-control" name="<?= $kind ?>" accept="<?= $kind==='Logo'?'.jpg,.jpeg,.png':'.pdf,.jpg,.jpeg,.png' ?>"><small>Maksimal 5 MB; kosongkan untuk mempertahankan file saat ini.</small><?php if(!empty($form[$kind.'StoredName'])): ?><p><a target="_blank" rel="noopener" href="<?= site_url('Pipeline_operator_company/file/'.$area.'/'.$kind) ?>"><?= html_escape($form[$kind.'OriginalName']) ?></a></p><?php if($kind==='Logo'): ?><img alt="Logo perusahaan" style="max-width:220px;max-height:110px;object-fit:contain" src="<?= site_url('Pipeline_operator_company/file/'.$area.'/Logo') ?>"><?php endif; ?><?php endif; ?></div><?php endforeach; ?></div><button class="btn btn-primary">Simpan Profil Perusahaan</button></form></div></div><?php else: ?><div class="alert alert-info">Belum ada area aktif pada akun ini. Hubungi administrator.</div><?php endif; ?></section></div>